    // ─────────── فصل ۱: بیلی پیلگریم ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "Billy Pilgrim", titlePersian = "بیلی پیلگریم",
        paragraphs = listOf(
            StoryParagraph("Billy Pilgrim has come unstuck in time.", "بیلی پیلگریم در زمان بی‌قید شده است."),
            StoryParagraph("He has no control over where he goes next, or when, or why.", "او هیچ کنترلی بر اینکه بعد کجا می‌رود ندارد، نه کِی، نه چرا."),
            StoryParagraph("He travels to different moments of his life, back and forth, without warning, without pattern, without meaning.", "او به لحظات مختلف زندگی‌اش سفر می‌کند، جلو و عقب، بدون هشدار، بدون الگو، بدون معنا."),
            StoryParagraph("One moment he is an old man in a hospital bed, and the next moment he is a young soldier in the snow.", "یک لحظه پیرمردی در تخت بیمارستان است و لحظه بعد سرباز جوانی در برف."),
            StoryParagraph("One moment he is a child on a beach in Cape Cod, and the next he is a prisoner of war in Germany.", "یک لحظه بچه‌ای در ساحلی در کیپ کد است و لحظه بعد اسیر جنگی در آلمان."),
            StoryParagraph("One moment he is a successful optometrist in Ilium, New York, and the next he is standing on a stage, making love to a former porn star on another planet.", "یک لحظه اپتومتریست موفقی در ایلیوم، نیویورک است و لحظه بعد روی صحنه‌ای ایستاده و با ستاره سابق فیلم‌های پورن در سیاره‌ای دیگر عشق می‌ورزد."),
            StoryParagraph("He does not choose these travels; they happen to him, as life happens to all of us, without asking permission.", "او این سفرها را انتخاب نمی‌کند؛ برایش اتفاق می‌افتند، همانطور که زندگی برای همه‌مان اتفاق می‌افتد، بی‌آنکه اجازه بپرسد."),
            StoryParagraph("He has learned, over time, to accept them; he has learned to say, 'So it goes,' and to move on.", "او در طول زمان آموخته که بپذیردشان؛ آموخته که بگوید «همینطوره» و ادامه دهد."),
            StoryParagraph("'So it goes' — this is his philosophy of life, his answer to death, his way of surviving the unsurvivable.", "«همینطوره» — این فلسفه زندگی‌اش است، پاسخش به مرگ، شیوه‌اش برای زنده ماندن در نماندنی."),
            StoryParagraph("Whenever someone dies, in the novel, the narrator simply says, 'So it goes.'", "هر وقت کسی در رمان می‌میرد، راوی به‌سادگی می‌گوید: «همینطوره.»"),
            StoryParagraph("It is a phrase that begins as a joke and ends as a prayer; it is a phrase that begins as numbness and ends as wisdom.", "عبارتی است که همچون شوخی آغاز می‌شود و همچون دعا پایان می‌یابد؛ عبارتی است که همچون بی‌حسی آغاز می‌شود و همچون خرد پایان می‌یابد."),
            StoryParagraph("The phrase appears more than one hundred times in the novel, and each time it means something slightly different.", "این عبارت بیش از صد بار در رمان ظاهر می‌شود و هر بار معنایی کمی متفاوت دارد."),
            StoryParagraph("Sometimes it means resignation, sometimes it means acceptance, sometimes it means grief too deep for words.", "گاهی به معنای تسلیم است، گاهی پذیرش، گاهی اندوهی عمیق‌تر از کلمات."),
            StoryParagraph("Sometimes it means that the narrator has given up trying to make sense of the world; sometimes it means that the world has no sense to make.", "گاهی به معنای این است که راوی از تلاش برای معنادار کردن جهان دست کشیده؛ گاهی به معنای این است که جهان معنایی برای ساختن ندارد."),
            StoryParagraph("Billy Pilgrim was born in 1922, in Ilium, New York, the only child of a barber and his wife.", "بیلی پیلگریم در ۱۹۲۲ در ایلیوم، نیویورک، تنها فرزند سلمانی و همسرش زاده شد."),
            StoryParagraph("He was a weak child, a skinny child, a child who was afraid of everything.", "بچه‌ای ضعیف بود، بچه‌ای لاغر، بچه‌ای که از همه چیز می‌ترسید."),
            StoryParagraph("He was afraid of the dark, of heights, of water, of strangers, of his own father.", "از تاریکی می‌ترسید، از بلندی، از آب، از غریبه‌ها، از پدر خودش."),
            StoryParagraph("His father, a barber, had a strange sense of humor; he thought it was funny to throw his young son into the deep end of the YMCA pool and let him drown almost.", "پدرش، سلمانی، حس شوخ‌طبعی عجیبی داشت؛ فکر می‌کرد خنده‌دار است که پسر کوچکش را به انتهای عمیق استخر YMCA بیندازد و تقریباً غرقش کند."),
            StoryParagraph("Billy almost drowned; Billy learned to swim; Billy also learned, that day, that his father was not his friend.", "بیلی تقریباً غرق شد؛ بیلی شنا یاد گرفت؛ بیلی آن روز یاد گرفت پدرش دوستش نیست."),
            StoryParagraph("He learned, that day, that the world was not safe; that the world was not kind; that the world did not care whether he lived or died.", "آن روز یاد گرفت جهان امن نیست؛ جهان مهربان نیست؛ جهان اهمیتی نمی‌دهد زنده می‌ماند یا می‌میرد."),
            StoryParagraph("He learned, that day, the first lesson of his life: that survival is not a matter of merit, but of chance.", "آن روز نخستین درس زندگی‌اش را آموخت: بقا مسئله شایستگی نیست، مسئله شانس است."),
            StoryParagraph("Billy was a mediocre student, a mediocre soldier, a mediocre man; he was not good at anything, and he was not bad at anything.", "بیلی دانش‌آموز متوسطی بود، سرباز متوسطی، مردی متوسط؛ در هیچ کاری خوب نبود و در هیچ کاری بد نبود."),
            StoryParagraph("He was, in other words, the perfect average American, and that is precisely why Vonnegut chose him as his hero.", "به عبارت دیگر، آمریکایی متوسط کاملی بود و دقیقاً به همین دلیل ونه‌گات او را قهرمانش برگزید."),
            StoryParagraph("Because the real hero of Slaughterhouse-Five is not Billy Pilgrim; it is the ordinary person who survives the ordinary horrors of the twentieth century.", "زیرا قهرمان واقعی کشتارگاه پنج بیلی پیلگریم نیست؛ انسان معمولی است که از وحشت‌های معمولی قرن بیستم زنده می‌ماند."),
            StoryParagraph("It is the soldier who does not want to fight, but fights anyway; the citizen who does not want to die, but dies anyway; the human who does not want to suffer, but suffers anyway.", "سربازی است که نمی‌خواهد بجنگد، اما به هر حال می‌جنگد؛ شهروندی است که نمی‌خواهد بمیرد، اما به هر حال می‌میرد؛ انسانی است که نمی‌خواهد رنج بکشد، اما به هر حال رنج می‌کشد."),
            StoryParagraph("Billy Pilgrim is not a hero; Billy Pilgrim is a witness; Billy Pilgrim is a survivor.", "بیلی پیلگریم قهرمان نیست؛ بیلی پیلگریم شاهد است؛ بیلی پیلگریم بازمانده است."),
            StoryParagraph("And survivors are not remembered by history; survivors are not celebrated by nations; survivors are simply there, in the background, saying, 'So it goes.'", "و بازماندگان را تاریخ به یاد نمی‌آورد؛ بازماندگان را ملت‌ها جشن نمی‌گیرند؛ بازماندگان تنها آنجا هستند، در پس‌زمینه، می‌گویند: «همینطوره.»"),
            StoryParagraph("And Billy Pilgrim, the weak child, the mediocre soldier, the average man, survived more than most.", "و بیلی پیلگریم، بچه ضعیف، سرباز متوسط، مرد متوسط، بیش از بیشتران زنده ماند."),
            StoryParagraph("He survived the war; he survived the bombing of Dresden; he survived a plane crash; he survived the death of his wife; he survived everything.", "از جنگ زنده ماند؛ از بمباران درسدن؛ از سقوط هواپیما؛ از مرگ همسرش؛ از همه چیز زنده ماند."),
            StoryParagraph("He survived because he did not fight; he survived because he did not resist; he survived because he did not care.", "زنده ماند چون نجنگید؛ زنده ماند چون مقاومت نکرد؛ زنده ماند چون اهمیت نمی‌داد."),
            StoryParagraph("And in surviving, he learned something that most of us never learn: that life is not a story with a beginning and a middle and an end.", "و در زنده ماندن، چیزی آموخت که بیشترمان هرگز نمی‌آموزیم: زندگی داستانی با آغاز و میانه و پایان نیست."),
            StoryParagraph("Life is a collection of moments, all happening at once, all equally real, all equally fleeting.", "زندگی مجموعه‌ای از لحظات است، همه با هم رخ می‌دهند، همه به یک اندازه واقعی، همه به یک اندازه گذرا."),
            StoryParagraph("And if we can learn to live in each moment, without clinging to the past or fearing the future, we can find peace.", "و اگر بتوانیم یاد بگیریم در هر لحظه زندگی کنیم، بدون چنگ زدن به گذشته یا ترس از آینده، می‌توانیم آرامش بیابیم."),
            StoryParagraph("This is the wisdom of the Tralfamadorians; this is the wisdom of Billy Pilgrim; this is, perhaps, the only wisdom available to us in a world of senseless violence.", "این خرد ترالفامادوری‌هاست؛ این خرد بیلی پیلگریم است؛ این، شاید، تنها خرد موجود برای ما در جهانی از خشونت بی‌معناست."),
            StoryParagraph("It is not a cheerful wisdom; it is not a comforting wisdom; but it is wisdom.", "خرد شادی نیست؛ خرد تسلی‌بخش نیست؛ اما خرد است."),
            StoryParagraph("And in a world like ours, in a century like ours, wisdom — any wisdom — is better than nothing.", "و در جهانی مثل جهان ما، در قرنی مثل قرن ما، خرد — هر خردی — از هیچ بهتر است."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )

    // ─────────── فصل ۲: جنگ ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The War", titlePersian = "جنگ",
        paragraphs = listOf(
            StoryParagraph("Billy Pilgrim was drafted into the army in 1944, at the age of twenty-two.", "بیلی پیلگریم در سال ۱۹۴۴، در سن بیست و دو سالگی، به ارتش فراخوانده شد."),
            StoryParagraph("He was sent to Europe, to fight against the Germans, in the last year of the Second World War.", "او به اروپا فرستاده شد، تا علیه آلمانی‌ها بجنگد، در آخرین سال جنگ جهانی دوم."),
            StoryParagraph("He was not a good soldier; he was clumsy, cowardly, confused; he did not know how to shoot a gun, or how to march, or how to survive.", "او سرباز خوبی نبود؛ دست‌وپا چلفتی، ترسو، گیج؛ نمی‌دانست چطور تیراندازی کند، یا چطور رژه برود، یا چطور زنده بماند."),
            StoryParagraph("He was assigned to the 106th Infantry Division, a unit that had been hastily assembled and sent to the front.", "به لشکر ۱۰۶ پیاده اختصاص یافت، یگانی که با عجله جمع‌آوری و به جبهه فرستاده شده بود."),
            StoryParagraph("His unit was sent to the front, to Belgium, to the Battle of the Bulge, where the Germans were making their last great counterattack.", "یگانش به جبهه فرستاده شد، به بلژیک، به نبرد بولج، جایی که آلمانی‌ها آخرین ضدحمله بزرگشان را انجام می‌دادند."),
            StoryParagraph("The Battle of the Bulge was the bloodiest battle of the war for the Americans; more than nineteen thousand American soldiers were killed.", "نبرد بولج خونین‌ترین نبرد جنگ برای آمریکایی‌ها بود؛ بیش از نوزده هزار سرباز آمریکایی کشته شدند."),
            StoryParagraph("Billy was separated from his unit; he wandered through the snow, cold, hungry, terrified.", "بیلی از یگانش جدا شد؛ در برف سرگردان شد، سرد، گرسنه، وحشت‌زده."),
            StoryParagraph("He had no food, no water, no weapon, no map, no compass; he had nothing but his fear.", "نه غذا داشت، نه آب، نه سلاح، نه نقشه، نه قطب‌نما؛ هیچ نداشت جز ترسش."),
            StoryParagraph("He met two other American soldiers: Roland Weary, a loud and cruel man, and two scouts, who soon left them behind.", "با دو سرباز آمریکایی دیگر آشنا شد: رولاند ویر، مردی پرصدا و ظالم، و دو پیشاهنگ که زودی رهایشان کردند."),
            StoryParagraph("Weary was obsessed with the war, with killing, with glory; he wanted to be a hero; he wanted to fight.", "ویر به جنگ وسواس داشت، به کشتن، به شکوه؛ می‌خواست قهرمان باشد؛ می‌خواست بجنگد."),
            StoryParagraph("He wore a Purple Heart that he had not earned; he had cut himself on a piece of shrapnel while drunk, and had claimed it was a wound from battle.", "نشان قلب ارغوانی بر تن داشت که به دست نیاورده بود؛ در مستی روی تکه‌ای ترکش خودش را زخمی کرده بود و ادعا کرده بود از نبرد است."),
            StoryParagraph("He talked constantly about the men he had killed, the battles he had won, the glories he had achieved.", "مدام از مردانی که کشته بود حرف می‌زد، از نبردهایی که برده بود، از شکوه‌هایی که به دست آورده بود."),
            StoryParagraph("None of it was true; none of it had happened; it was all a fantasy, a lie, a story he told himself to make himself feel important.", "هیچ‌کدام درست نبود؛ هیچ‌کدام اتفاق نیفتاده بود؛ همه‌اش خیال بود، دروغ، داستانی که به خودش می‌گفت تا حس کند مهم است."),
            StoryParagraph("Billy did not want to fight; Billy did not want to kill; Billy did not want to die.", "بیلی نمی‌خواست بجنگد؛ بیلی نمی‌خواست بکشد؛ بیلی نمی‌خواست بمیرد."),
            StoryParagraph("He wanted to go home; he wanted to see his mother; he wanted to be somewhere warm, somewhere safe, somewhere far from the war.", "می‌خواست به خانه برود؛ می‌خواست مادرش را ببیند؛ می‌خواست جایی گرم باشد، جایی امن، جایی دور از جنگ."),
            StoryParagraph("But the war did not care what Billy wanted; the war did not care about anyone.", "اما جنگ اهمیتی نمی‌داد بیلی چه می‌خواهد؛ جنگ به هیچ‌کس اهمیتی نمی‌داد."),
            StoryParagraph("Weary and Billy were captured by German soldiers; they were taken to a prison camp; they were put in a boxcar with other prisoners.", "ویر و بیلی توسط سربازان آلمانی اسیر شدند؛ به اردوگاه اسرا برده شدند؛ در واگن باری با دیگر اسرا گذاشته شدند."),
            StoryParagraph("The boxcar was crowded, airless, filthy; men died there, every night; their bodies were left among the living, because there was no room to move them.", "واگن باری پر، بی‌هوا، کثیف بود؛ مردان آنجا می‌مردند، هر شب؛ بدن‌هایشان میان زندگان رها می‌شد، چون جایی برای جابه‌جایشان نبود."),
            StoryParagraph("The car was so crowded that the prisoners could not sit down; they had to stand, for days, for weeks.", "واگن آنقدر پر بود که اسرا نمی‌توانستند بنشینند؛ باید می‌ایستادند، روزها، هفته‌ها."),
            StoryParagraph("There was a bucket in one corner for a toilet; it was emptied once a day, through a small window, onto the tracks.", "سطل‌زباله‌ای در یک گوشه برای توالت بود؛ روزی یک بار از پنجره‌ای کوچک روی ریل‌ها خالی می‌شد."),
            StoryParagraph("The smell was unbearable; the hunger was unbearable; the fear was unbearable.", "بو غیرقابل تحمل بود؛ گرسنگی غیرقابل تحمل بود؛ ترس غیرقابل تحمل بود."),
            StoryParagraph("Roland Weary died on the way, of gangrene in his feet; before he died, he told everyone that Billy had killed him.", "رولاند ویر در راه مرد، از قانقاریا در پاهایش؛ پیش از مرگ، به همه گفت بیلی او را کشته."),
            StoryParagraph("It was a lie; it was the last act of a cruel and petty man; but people believed it.", "دروغ بود؛ آخرین عمل مردی ظالم و حقیر بود؛ اما مردم باور کردند."),
            StoryParagraph("Billy did not know he had been accused; Billy did not know that a man named Paul Lazzaro had sworn to avenge Weary's death.", "بیلی نمی‌دانست متهم شده؛ نمی‌دانست مردی به نام پاول لازارو قسم خورده انتقام مرگ ویر را بگیرد."),
            StoryParagraph("Paul Lazzaro was a small, vicious man from Cicero, Illinois; he had killed dogs, cats, and even people, and he had never been caught.", "پاول لازارو مردی کوچک و وحشی از سیسرو، ایلینوی بود؛ سگ‌ها کشته بود، گربه‌ها و حتی آدم‌ها و هرگز دستگیر نشده بود."),
            StoryParagraph("He had a saying: 'You can have anything you want, if you want it bad enough, and if you have the nerve to take it.'", "می‌گفت: «هر چیزی که بخواهی می‌توانی داشته باشی، اگر به اندازه کافی بخواهی و اگر جرات گرفتنش را داشته باشی.»"),
            StoryParagraph("He had never wanted anything as much as he wanted revenge for Roland Weary; he had sworn to find Billy Pilgrim and kill him.", "هرگز چیزی را به اندازه انتقام رولاند ویر نخواسته بود؛ قسم خورده بود بیلی پیلگریم را پیدا کند و بکشدش."),
            StoryParagraph("It would take him more than thirty years to fulfill his oath; but he would fulfill it, in the end, in a public park in Chicago, in 1976.", "سی سال طول می‌کشید تا قسمش را انجام دهد؛ اما در پایان انجامش می‌داد، در پارکی عمومی در شیکاگو، در ۱۹۷۶."),
            StoryParagraph("Billy would learn, years later, that his death had been ordered in that boxcar, by dying men, for no reason at all.", "بیلی سال‌ها بعد می‌فهمید که مرگش در آن واگن باری سفارش داده شده، توسط مردان در حال مرگ، بدون هیچ دلیل."),
            StoryParagraph("So it goes.", "همینطوره."),
            StoryParagraph("The prisoners arrived at a camp in Germany; they were given uniforms, food, and a place to sleep.", "اسرا به اردوگاهی در آلمان رسیدند؛ لباس، غذا و جایی برای خوابیدن به آن‌ها داده شد."),
            StoryParagraph("The camp was called Stalag IV-B; it held more than thirty thousand prisoners, from every country in Europe.", "اردوگاه اشتالاگ ۴-ب نام داشت؛ بیش از سی هزار اسیر در آن بودند، از هر کشور اروپا."),
            StoryParagraph("Billy was assigned to a work detail; he worked in a factory that made malt syrup for pregnant women.", "بیلی به گروه کاری‌ای اختصاص یافت؛ در کارخانه‌ای کار می‌کرد که شربت مالت برای زنان باردار می‌ساخت."),
            StoryParagraph("It was not a bad job; it was not a dangerous job; it was simply a job, a way of passing the time, a way of surviving.", "کار بدی نبود؛ کار خطرناکی نبود؛ تنها کاری بود، راهی برای گذراندن وقت، راهی برای زنده ماندن."),
            StoryParagraph("The vitamin syrup was loaded onto trucks and sent to Germany; the prisoners were told that it was for the Führer's pregnant mistresses.", "شربت ویتامین روی کامیون‌ها بار زده می‌شد و به آلمان فرستاده می‌شد؛ به اسرا گفته می‌شد که برای معشوقه‌های باردار پیشواست."),
            StoryParagraph("But Billy did not know, and did not care; he simply did what he was told, and waited for the war to end.", "اما بیلی نمی‌دانست و اهمیت نمی‌داد؛ تنها آنچه به او گفته می‌شد انجام می‌داد و منتظر ماند تا جنگ تمام شود."),
            StoryParagraph("Billy worked in the factory, and he learned German, and he made a few friends, and he waited.", "بیلی در کارخانه کار کرد و آلمانی یاد گرفت و چند دوست پیدا کرد و منتظر ماند."),
            StoryParagraph("He met an Englishman, a former teacher, who told him about Dresden, the beautiful city, the city of art.", "با انگلیسی‌ای آشنا شد، معلم سابقی، که درباره درسدن برایش گفت، شهر زیبا، شهر هنر."),
            StoryParagraph("Dresden was where Billy and the other prisoners were sent next; Dresden was where Billy's life would change forever.", "درسدن جایی بود که بیلی و دیگر اسرا بعد به آن فرستاده شدند؛ درسدن جایی بود که زندگی بیلی برای همیشه تغییر می‌کرد."),
            StoryParagraph("Dresden was a city of no military importance; it had no factories, no troops, no strategic value; it was a city of civilians, of women and children and old men.", "درسدن شهری بدون اهمیت نظامی بود؛ کارخانه‌ای نداشت، نه سربازی، نه ارزش استراتژیک؛ شهری بود از غیرنظامیان، از زنان و کودکان و پیرمردان."),
            StoryParagraph("But Dresden was destroyed anyway; Dresden was firebombed by the Allies in February, 1945.", "اما درسدن به هر حال نابود شد؛ درسدن توسط متفقین در فوریه ۱۹۴۵ بمباران آتشین شد."),
            StoryParagraph("Over one hundred and thirty-five thousand people were killed in a single night; it was one of the worst atrocities of the war.", "بیش از صد و سی و پنج هزار نفر در یک شب کشته شدند؛ یکی از بدترین جنایات جنگ بود."),
            StoryParagraph("Billy survived because he was in a meat locker, in a slaughterhouse, five stories below the ground.", "بیلی زنده ماند چون در سردخانه گوشت بود، در کشتارگاهی، پنج طبقه زیر زمین."),
            StoryParagraph("The slaughterhouse was called Schlachthof-fünf; it was Slaughterhouse-Five.", "کشتارگاه شلاخت‌هوف‌فونف نام داشت؛ یعنی کشتارگاه پنج."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )

    // ─────────── فصل ۳: ترالفامادور ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Tralfamadore", titlePersian = "ترالفامادور",
        paragraphs = listOf(
            StoryParagraph("Billy Pilgrim was kidnapped by aliens from the planet Tralfamadore on his daughter's wedding night, in 1967.", "بیلی پیلگریم در شب عروسی دخترش، در ۱۹۶۷، توسط موجودات فضایی از سیاره ترالفامادور ربوده شد."),
            StoryParagraph("He was fifty years old; he was in his bed; he was sleeping; and then he was not on Earth anymore.", "پنجاه ساله بود؛ در تختش بود؛ در خواب؛ و بعد دیگر روی زمین نبود."),
            StoryParagraph("The Tralfamadorians were shaped like plumber's friends, two feet tall, with green skin and a single eye in the middle of their heads.", "ترالفامادوری‌ها شکل چاه‌بازکن بودند، دو فوت قد، با پوست سبز و یک چشم در میان سرشان."),
            StoryParagraph("They had suction cups at the ends of their arms, which they used to grip and to communicate.", "در انتهای بازوهایشان فنجان‌های مکنده داشتند که برای گرفتن و برقراری ارتباط استفاده می‌کردند."),
            StoryParagraph("They could see in four dimensions; they could see time the way we see space; they could see all moments at once.", "می‌توانستند در چهار بُعد ببینند؛ زمان را همانطور می‌دیدند که ما مکان را؛ می‌توانستند همه لحظات را یکجا ببینند."),
            StoryParagraph("They did not experience time as a line, but as a landscape; they did not experience events as happening one after another, but as all happening at once.", "زمان را همچون خط تجربه نمی‌کردند، بلکه همچون منظره‌ای؛ رویدادها را همچون رخ دادن یکی پس از دیگری تجربه نمی‌کردند، بلکه همچون رخ دادن همه با هم."),
            StoryParagraph("'Where am I?' Billy asked.", "بیلی پرسید: «کجایم؟»"),
            StoryParagraph("'You are in a zoo on the planet Tralfamadore,' one of them said, in Billy's mind, because they did not speak with voices.", "یکی‌شان گفت: «در باغ‌وحشی‌ای در سیاره ترالفامادور هستی.» در ذهن بیلی، چون با صدا صحبت نمی‌کردند."),
            StoryParagraph("'Why am I here?' Billy asked.", "بیلی پرسید: «چرا اینجام؟»"),
            StoryParagraph("'Because we are studying you,' they said. 'Because we want to understand human beings.'", "گفتند: «چون داریم مطالعه‌ات می‌کنیم. چون می‌خواهیم انسان‌ها را بفهمیم.»"),
            StoryParagraph("'Why?' Billy asked.", "بیلی پرسید: «چرا؟»"),
            StoryParagraph("'Because we are curious,' they said. 'Because you are interesting. Because you do so many things that we do not understand.'", "گفتند: «چون کنجکاویم. چون جالبی. چون کارهای زیادی می‌کنید که ما نمی‌فهمیم.»"),
            StoryParagraph("'What things?' Billy asked.", "بیلی پرسید: «چه کارها؟»"),
            StoryParagraph("'War,' they said. 'Death. Time. Why do you fight wars? Why do you kill each other? Why do you mourn your dead? Why do you fear your future?'", "گفتند: «جنگ. مرگ. زمان. چرا می‌جنگید؟ چرا همدیگر را می‌کشید؟ چرا برای مردگانتان عزاداری می‌کنید؟ چرا از آینده‌تان می‌ترسید؟»"),
            StoryParagraph("Billy did not know how to answer.", "بیلی نمی‌دانست چطور پاسخ دهد."),
            StoryParagraph("'We do not understand,' they said. 'We see all time. We see all moments. We know what will happen. We know that you will die. We know that everyone will die. But we do not mourn. We do not fear. We simply accept.'", "گفتند: «نمی‌فهمیم. ما تمام زمان را می‌بینیم. همه لحظات را می‌بینیم. می‌دانیم چه اتفاقی می‌افتد. می‌دانیم که می‌میری. می‌دانیم که همه می‌میرند. اما عزاداری نمی‌کنیم. نمی‌ترسیم. تنها می‌پذیریم.»"),
            StoryParagraph("'What do you mean?' Billy asked.", "بیلی پرسید: «منظورت چیست؟»"),
            StoryParagraph("'We mean that we do not see time as a line, with a past, a present, and a future. We see it as a landscape, with all moments visible at once.'", "گفتند: «یعنی ما زمان را همچون خط نمی‌بینیم، با گذشته، حال و آینده. همچون منظره‌ای می‌بینیم، با همه لحظات به طور همزمان قابل مشاهده.»"),
            StoryParagraph("'And in that landscape, no one ever truly dies. They are just... not in this moment.'", "«و در آن منظره، هیچ‌کس هرگز به‌راستی نمی‌میرد. تنها... در این لحظه نیست.»"),
            StoryParagraph("'So death is not real?' Billy asked.", "بیلی پرسید: «پس مرگ واقعی نیست؟»"),
            StoryParagraph("'Death is real,' they said. 'But it is not the end. It is simply one moment in a life of many moments.'", "گفتند: «مرگ واقعی است. اما پایان نیست. تنها یک لحظه است در زندگی‌ای از لحظات بسیار.»"),
            StoryParagraph("'And so,' they said, 'when we see a corpse, we do not think, 'How terrible.' We think, 'So it goes.' We think, 'This person is still alive in other moments.'", "گفتند: «و بنابراین، وقتی جسدی می‌بینیم، فکر نمی‌کنیم 'چه هولناک.' فکر می‌کنیم 'همینطوره.' فکر می‌کنیم 'این شخص در لحظات دیگر هنوز زنده است.'»"),
            StoryParagraph("'That is a very comforting philosophy,' Billy said.", "بیلی گفت: «این فلسفه خیلی تسلی‌بخشی است.»"),
            StoryParagraph("'Yes,' they said. 'It is.'", "گفتند: «بله. هست.»"),
            StoryParagraph("'And is it true?' Billy asked.", "بیلی پرسید: «و درست است؟»"),
            StoryParagraph("'It is true for us,' they said. 'Whether it is true for you, we cannot say. But we do not see why it should not be.'", "گفتند: «برای ما درست است. اینکه برای تو درست است یا نه، نمی‌توانیم بگوییم. اما نمی‌بینیم چرا نباید باشد.»"),
            StoryParagraph("'And if it is not true?' Billy asked.", "بیلی پرسید: «و اگر درست نباشد؟»"),
            StoryParagraph("'Then,' they said, 'it is still a comforting lie. And a comforting lie is better than an un comforting truth.'", "گفتند: «پس، هنوز دروغی تسلی‌بخش است. و دروغی تسلی‌بخش از حقیقتی غیرتسلی‌بخش بهتر است.»"),
            StoryParagraph("Billy thought about this for a long time; he thought about the war, about Dresden, about all the death he had seen.", "بیلی مدت طولانی به این فکر کرد؛ به جنگ فکر کرد، به درسدن، به تمام مرگی که دیده بود."),
            StoryParagraph("He thought about his wife, who had died in a car accident; he thought about himself, about his own death, which he knew was coming.", "به همسرش فکر کرد، که در حادثه ماشین مرده بود؛ به خودش فکر کرد، به مرگ خودش، که می‌دانست در راه است."),
            StoryParagraph("And he decided that the Tralfamadorians were right; he decided that death was not the end; he decided that he would no longer mourn, no longer fear, no longer suffer.", "و تصمیم گرفت ترالفامادوری‌ها حق دارند؛ تصمیم گرفت مرگ پایان نیست؛ تصمیم گرفت دیگر عزاداری نکند، دیگر نترسد، دیگر رنج نکشد."),
            StoryParagraph("From that day on, Billy Pilgrim accepted everything that happened to him, and everything that happened to everyone he loved.", "از آن روز، بیلی پیلگریم هر چیزی که برایش اتفاق می‌افتاد را پذیرفت و هر چیزی که برای هر کسی که دوستش داشت اتفاق می‌افتاد."),
            StoryParagraph("He accepted joy and sorrow, life and death, love and loss; he accepted the whole terrible, beautiful mystery of existence.", "شادی را پذیرفت و اندوه، زندگی و مرگ، عشق و فقدان؛ تمام رمز هولناک و زیبای هستی را پذیرفت."),
            StoryParagraph("And whenever someone died, in the novel, in his life, in his memory, Billy simply said, 'So it goes.'", "و هر وقت کسی می‌مرد، در رمان، در زندگی‌اش، در حافظه‌اش، بیلی به‌سادگی می‌گفت: «همینطوره.»"),
            StoryParagraph("Some readers have found this philosophy troubling; some readers have found it comforting.", "برخی خوانندگان این فلسفه را نگران‌کننده یافته‌اند؛ برخی آن را تسلی‌بخش."),
            StoryParagraph("Vonnegut himself was ambivalent about it; he never said that the Tralfamadorians were right, and he never said they were wrong.", "خود ونه‌گات درباره‌اش دوگانه بود؛ هرگز نگفت ترالفامادوری‌ها حق دارند و هرگز نگفت اشتباه می‌کنند."),
            StoryParagraph("He simply presented their philosophy, and let the reader decide whether to accept it or to reject it.", "تنها فلسفه‌شان را ارائه کرد و گذاشت خواننده تصمیم بگیرد بپذیرد یا رد کند."),
            StoryParagraph("But he did say one thing: that in a world of senseless suffering, sometimes the only thing you can do is say, 'So it goes.'", "اما یک چیز گفت: در جهانی از رنج بی‌معنا، گاهی تنها کاری که می‌توانی بکنی این است که بگویی: «همینطوره.»"),
            StoryParagraph("And that, perhaps, is the deepest message of the novel.", "و این، شاید، عمیق‌ترین پیام رمان است."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )

    // ─────────── فصل ۴: زندگی پس از جنگ ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Life After the War", titlePersian = "زندگی پس از جنگ",
        paragraphs = listOf(
            StoryParagraph("After the war, Billy Pilgrim returned to America, to Ilium, New York, to the small life he had left behind.", "بعد از جنگ، بیلی پیلگریم به آمریکا بازگشت، به ایلیوم، نیویورک، به زندگی کوچکی که رها کرده بود."),
            StoryParagraph("He enrolled in optometry school; he studied hard; he graduated; he became a doctor of optometry.", "در مدرسه اپتومتری ثبت‌نام کرد؛ سخت درس خواند؛ فارغ‌التحصیل شد؛ دکتر اپتومتری شد."),
            StoryParagraph("His father had wanted him to be an optometrist; his father had believed that optometry was the safest profession in America.", "پدرش می‌خواست او اپتومتریست شود؛ پدرش معتقد بود اپتومتری امن‌ترین حرفه آمریکاست."),
            StoryParagraph("'You will spend your days in a warm room,' his father had told him. 'You will look into people's eyes, and you will help them to see.'", "پدرش به او گفته بود: «روزهایت را در اتاقی گرم می‌گذرانی. به چشمان مردم نگاه می‌کنی و به آن‌ها کمک می‌کنی ببینند.»"),
            StoryParagraph("'You will not have to fight,' his father had said. 'You will not have to kill.'", "پدرش گفته بود: «مجبور نمی‌شوی بجنگی. مجبور نمی‌شوی بکشی.»"),
            StoryParagraph("But Billy did fight; Billy did see death; Billy did see more than any optometrist should ever see.", "اما بیلی جنگید؛ بیلی مرگ دید؛ بیلی بیش از آنکه هر اپتومتریستی باید ببیند دید."),
            StoryParagraph("He married the daughter of the school's founder, a fat, homely girl named Valencia Merble, who loved him more than he loved her.", "با دختر بنیان‌گذار مدرسه ازدواج کرد، دختری چاق و بی‌جلوه به نام والنسیا مربل، که بیشتر از آنکه او دوستش داشته باشد، دوستش داشت."),
            StoryParagraph("Her father gave Billy a house, and a car, and a position in the family business; Billy became a rich man, a successful man, a respected man.", "پدرش خانه‌ای به بیلی داد و ماشینی و موقعیتی در تجارت خانوادگی؛ بیلی مرد ثروتمندی شد، مرد موفقی، مرد محترمی."),
            StoryParagraph("The house was a mansion in the nicest part of Ilium, with a swimming pool and a tennis court and a greenhouse full of orchids.", "خانه عمارتی در بهترین بخش ایلیوم بود، با استخری و زمین تنیسی و گلخانه‌ای پر از ثعلب."),
            StoryParagraph("The car was a Cadillac, cream-colored, with red leather seats and a radio that could play the top hits of the day.", "ماشین کادیلاکی بود، کرمرنگ، با صندلی‌های چرمی سرخ و رادیویی که می‌توانست ترانه‌های برتر روز را پخش کند."),
            StoryParagraph("The business was a chain of optometry shops, scattered across the state, each one making a small fortune for the family.", "کسب‌وکار زنجیره‌ای از مغازه‌های اپتومتری بود، پراکنده در سراسر ایالت، هر یک ثروت کوچکی برای خانواده می‌ساخت."),
            StoryParagraph("But Billy was not happy; Billy had never been happy; Billy did not know how to be happy.", "اما بیلی خوشحال نبود؛ بیلی هرگز خوشحال نبوده بود؛ بیلی نمی‌دانست چطور خوشحال باشد."),
            StoryParagraph("He had two children: a son named Robert, who grew up to be a Green Beret, and a daughter named Barbara, who grew up to be a worried, controlling woman.", "او دو فرزند داشت: پسری به نام رابرت، که به کلاه‌سبز تبدیل شد و دختری به نام باربارا، که به زنی نگران و کنترل‌گر تبدیل شد."),
            StoryParagraph("Robert went to Vietnam; Robert became an alcoholic; Robert was dishonorably discharged; Robert disappeared from his father's life.", "رابرت به ویتنام رفت؛ رابرت الکلی شد؛ رابرت با بدنامی اخراج شد؛ رابرت از زندگی پدرش ناپدید شد."),
            StoryParagraph("Barbara stayed close; Barbara worried about her father; Barbara wanted to protect him from himself.", "باربارا نزدیک ماند؛ باربارا نگران پدرش بود؛ باربارا می‌خواست از خودش محافظتش کند."),
            StoryParagraph("Barbara read books about mental illness; Barbara talked to doctors; Barbara believed that her father was insane.", "باربارا کتاب‌هایی درباره بیماری روانی می‌خواند؛ باربارا با دکترها صحبت می‌کرد؛ باربارا معتقد بود پدرش دیوانه است."),
            StoryParagraph("But Billy was not insane; Billy was simply unstuck; Billy was simply seeing things differently than most people see them.", "اما بیلی دیوانه نبود؛ بیلی تنها بی‌قید شده بود؛ بیلی تنها چیزها را متفاوت از بیشتر مردم می‌دید."),
            StoryParagraph("Billy spent his days in his office, fitting glasses on people, listening to their complaints, pretending to care.", "بیلی روزهایش را در مطبش می‌گذراند، عینک روی صورت مردم می‌گذاشت، به شکایاتشان گوش می‌داد، تظاهر به اهمیت دادن می‌کرد."),
            StoryParagraph("He heard the same complaints every day: 'I can't see the newspaper,' 'I can't see the television,' 'I can't see my wife's face.'", "هر روز همان شکایات را می‌شنید: «نمی‌توانم روزنامه را ببینم،» «نمی‌توانم تلویزیون را ببینم،» «نمی‌توانم صورت همسرم را ببینم.»"),
            StoryParagraph("He fitted them with glasses, and they were grateful, and they paid him, and they went away, and they came back the next year.", "عینک برایشان می‌گذاشت و سپاسگزار بودند و پولش را می‌دادند و می‌رفتند و سال بعد برمی‌گشتند."),
            StoryParagraph("Billy spent his nights alone, in his basement, reading science fiction novels, dreaming of Tralfamadore.", "بیلی شب‌هایش را تنها می‌گذراند، در زیرزمینش، رمان‌های علمی-تخیلی می‌خواند، رؤیای ترالفامادور می‌دید."),
            StoryParagraph("He had become, over the years, a kind of alien himself; he had become a man who did not quite belong on Earth.", "در طول سال‌ها، خودش نوعی موجود فضایی شده بود؛ مردی شده بود که کاملاً به زمین تعلق نداشت."),
            StoryParagraph("He watched television, and he read newspapers, and he saw the wars, the famines, the cruelties of the world, and he said, 'So it goes.'", "تلویزیون تماشا می‌کرد و روزنامه می‌خواند و جنگ‌ها را می‌دید، قحطی‌ها، بی‌رحمی‌های جهان را و می‌گفت: «همینطوره.»"),
            StoryParagraph("He watched the assassinations of Kennedy, and King, and Kennedy again; he watched the Vietnam War; he watched the students shot at Kent State.", "ترورهای کندی را تماشا کرد و کینگ و دوباره کندی؛ جنگ ویتنام را تماشا کرد؛ دانشجویان کشته‌شده در کنت استیت را تماشا کرد."),
            StoryParagraph("And for each death, for each horror, for each senseless tragedy, he simply said, 'So it goes.'", "و برای هر مرگی، برای هر وحشتی، برای هر تراژدی بی‌معنایی، تنها می‌گفت: «همینطوره.»"),
            StoryParagraph("Some people thought Billy was a fool; some thought he was a saint; some thought he was simply broken.", "برخی مردم فکر می‌کردند بیلی احمق است؛ برخی فکر می‌کردند قدیس است؛ برخی فکر می‌کردند تنها شکسته است."),
            StoryParagraph("But Billy did not care what people thought; Billy had stopped caring long ago; Billy had learned that caring does not change anything.", "اما بیلی اهمیتی نمی‌داد مردم چه فکر می‌کنند؛ بیلی مدت‌ها پیش از اهمیت دادن دست کشیده بود؛ بیلی آموخته بود اهمیت دادن چیزی را عوض نمی‌کند."),
            StoryParagraph("The only thing that changes anything, Billy had learned, is the passing of time; and time passes regardless of whether we care or not.", "تنها چیزی که چیزی را عوض می‌کند، بیلی آموخته بود، گذر زمان است؛ و زمان می‌گذرد بی‌آنکه اهمیت بدهد ما اهمیت می‌دهیم یا نه."),
            StoryParagraph("And then, one night, the aliens came back.", "و بعد، یک شب، موجودات فضایی برگشتند."),
            StoryParagraph("They took Billy to Tralfamadore again; they put him in a zoo, with a mate they had chosen for him: Montana Wildhack, a movie star who had disappeared years before.", "بیلی را دوباره به ترالفامادور بردند؛ او را در باغ‌وحشی‌ای گذاشتند، با جفتی که برایش انتخاب کرده بودند: مونتانا وایلدهاک، ستاره فیلمی که سال‌ها پیش ناپدید شده بود."),
            StoryParagraph("Montana was young and beautiful; Montana was also lonely and lost; Montana did not know why she had been chosen.", "مونتانا جوان و زیبا بود؛ مونتانا تنها و گمگشته هم بود؛ مونتانا نمی‌دانست چرا انتخاب شده."),
            StoryParagraph("Billy and Montana lived together in the zoo; they made love; they had a child; they were happy, in their way, in their strange, captive way.", "بیلی و مونتانا با هم در باغ‌وحشی زندگی کردند؛ عشق ورزیدند؛ بچه‌دار شدند؛ خوشحال بودند، به شیوه خودشان، به شیوه عجیب و اسیرشده‌شان."),
            StoryParagraph("Tourists came from all over the galaxy to see them; they stared at the humans as humans stare at apes; they threw food; they took pictures; they did not understand.", "جهانگردان از سراسر کهکشان برای دیدنشان می‌آمدند؛ به انسان‌ها خیره می‌شدند همانطور که انسان‌ها به میمون‌ها خیره می‌شوند؛ غذا پرت می‌کردند؛ عکس می‌گرفتند؛ نمی‌فهمیدند."),
            StoryParagraph("Billy did not mind; Billy had long ago stopped minding anything; Billy had learned to accept.", "بیلی اهمیت نمی‌داد؛ بیلی مدت‌ها پیش از اهمیت دادن به هر چیزی دست کشیده بود؛ بیلی یاد گرفته بود بپذیرد."),
            StoryParagraph("He had learned, from the Tralfamadorians, the deepest truth of existence: that everything happens, and nothing matters, and both of these things are true at the same time.", "او از ترالفامادوری‌ها عمیق‌ترین حقیقت هستی را آموخته بود: که همه چیز اتفاق می‌افتد و هیچ چیز مهم نیست و هر دو این چیزها همزمان درست هستند."),
            StoryParagraph("And in that paradox, in that contradiction, in that impossible truth, Billy Pilgrim found peace.", "و در آن پارادوکس، در آن تناقض، در آن حقیقت ناممکن، بیلی پیلگریم آرامش یافت."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )

    // ─────────── فصل ۵: مرگ‌ها ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Deaths", titlePersian = "مرگ‌ها",
        paragraphs = listOf(
            StoryParagraph("Billy Pilgrim died on February 13, 1976, in Chicago, at the age of fifty-four, in a public park, under a clear blue sky.", "بیلی پیلگریم در ۱۳ فوریه ۱۹۷۶، در شیکاگو، در سن پنجاه و چهار سالگی، در پارکی عمومی، زیر آسمانی آبی و صاف مرد."),
            StoryParagraph("He was giving a speech about time travel, about Tralfamadore, about the wisdom of accepting all things, when a man named Paul Lazzaro shot him.", "او درباره سفر در زمان صحبت می‌کرد، درباره ترالفامادور، درباره خرد پذیرش همه چیز، وقتی مردی به نام پاول لازارو شلیکش کرد."),
            StoryParagraph("Paul Lazzaro had been in the boxcar with Billy and Weary; Paul Lazzaro had sworn revenge for Weary's death.", "پاول لازارو در واگن باری با بیلی و ویر بوده بود؛ پاول لازارو قسم انتقام مرگ ویر را خورده بود."),
            StoryParagraph("Weary had lied, but Lazzaro did not care; Lazzaro wanted blood; Lazzaro had been waiting for this moment for more than thirty years.", "ویر دروغ گفته بود اما لازارو اهمیتی نمی‌داد؛ لازارو خون می‌خواست؛ لازارو بیش از سی سال منتظر این لحظه بود."),
            StoryParagraph("Lazzaro was an old man now, but his hatred was young; Lazzaro was dying of cancer, but his hatred was alive.", "لازارو حالا پیرمردی بود اما نفرتش جوان بود؛ لازارو از سرطان می‌مرد اما نفرتش زنده بود."),
            StoryParagraph("He had tracked Billy for years; he had followed Billy across the country; he had waited for the perfect moment.", "سال‌ها بیلی را تعقیب کرده بود؛ در سراسر کشور دنبالش کرده بود؛ منتظر لحظه کامل مانده بود."),
            StoryParagraph("And now, in a public park in Chicago, on a clear February morning, he had his moment.", "و حالا، در پارکی عمومی در شیکاگو، در صبح صاف فوریه‌ای، لحظه‌اش رسیده بود."),
            StoryParagraph("Billy saw the gun, saw the flash, felt the bullet, fell to the ground; and as he fell, he thought, 'So it goes.'", "بیلی اسلحه را دید، جرقه را دید، گلوله را حس کرد، روی زمین افتاد؛ و همانطور که می‌افتاد، فکر کرد: «همینطوره.»"),
            StoryParagraph("He had lived and relived his life many times; he had seen his own death many times; he knew it was coming, and he was not afraid.", "زندگی‌اش را بارها زندگی و دوباره زندگی کرده بود؛ مرگ خودش را بارها دیده بود؛ می‌دانست می‌آید و نمی‌ترسید."),
            StoryParagraph("Because, as the Tralfamadorians had taught him, death is not the end; it is simply one moment among many.", "زیرا، همانطور که ترالفامادوری‌ها به او آموخته بودند، مرگ پایان نیست؛ تنها یک لحظه است میان بسیاری."),
            StoryParagraph("And in that moment, in that final moment, Billy Pilgrim smiled.", "و در آن لحظه، در آن لحظه نهایی، بیلی پیلگریم لبخند زد."),
            StoryParagraph("So it goes.", "همینطوره."),
            StoryParagraph("But Billy Pilgrim was not the only one to die in Slaughterhouse-Five; the novel is full of deaths, and each one is marked with the same phrase.", "اما بیلی پیلگریم تنها کسی نبود که در کشتارگاه پنج مرد؛ رمان پر از مرگ است و هر یک با همان عبارت مشخص می‌شود."),
            StoryParagraph("Over one hundred and thirty-five thousand people died in the bombing of Dresden, and each of them, in the novel, is mourned with 'So it goes.'", "بیش از صد و سی و پنج هزار نفر در بمباران درسدن مردند و هر یک، در رمان، با «همینطوره» عزاداری می‌شوند."),
            StoryParagraph("The novel does not describe the bombing in detail; Vonnegut could not describe it in detail; Vonnegut could not find the words.", "رمان بمباران را با جزئیات توصیف نمی‌کند؛ ونه‌گات نمی‌توانست با جزئیات توصیفش کند؛ ونه‌گات نمی‌توانست کلمات را بیابد."),
            StoryParagraph("Instead, he simply says that Billy and the other prisoners were in the slaughterhouse, five stories below ground, when the bombs fell.", "در عوض، تنها می‌گوید بیلی و دیگر اسرا در کشتارگاه بودند، پنج طبقه زیر زمین، وقتی بمب‌ها افتادند."),
            StoryParagraph("When they came out, the city was gone; when they came out, everyone was dead; when they came out, there was nothing left.", "وقتی بیرون آمدند، شهر رفته بود؛ وقتی بیرون آمدند، همه مرده بودند؛ وقتی بیرون آمدند، هیچ نمانده بود."),
            StoryParagraph("Billy's father died, in his sleep, in 1945, and Billy said, 'So it goes.'", "پدر بیلی در ۱۹۴۵، در خواب، مرد و بیلی گفت: «همینطوره.»"),
            StoryParagraph("Billy's mother died, in a nursing home, in 1966, and Billy said, 'So it goes.'", "مادر بیلی در ۱۹۶۶، در خانه سالمندان، مرد و بیلی گفت: «همینطوره.»"),
            StoryParagraph("Billy's wife, Valencia, died in a car accident, on her way to see Billy in the hospital after his plane crash.", "همسر بیلی، والنسیا، در حادثه ماشین مرد، در راه دیدن بیلی در بیمارستان پس از سقوط هواپیمایش."),
            StoryParagraph("She had been driving recklessly, in a panic, because she loved him, because she was worried, because she could not bear the thought of losing him.", "او با بی‌احتیاطی رانندگی می‌کرد، از وحشت، چون دوستش داشت، چون نگران بود، چون نمی‌توانست فکر از دست دادنش را تحمل کند."),
            StoryParagraph("The exhaust pipe of her car had broken; the carbon monoxide had crept into the car; she had died without knowing what was happening.", "لوله اگزوز ماشینش شکسته بود؛ مونوکسید کربن به داخل ماشین خزیده بود؛ او بدون دانستن آنچه می‌گذرد مرده بود."),
            StoryParagraph("Billy was in the hospital, recovering from his plane crash; when they told him about Valencia, he did not cry; he said, 'So it goes.'", "بیلی در بیمارستان بود و از سقوط هواپیمایش بهبود می‌یافت؛ وقتی درباره والنسیا به او گفتند، گریه نکرد؛ گفت: «همینطوره.»"),
            StoryParagraph("Billy's son, Robert, died in Vietnam, or disappeared in Vietnam, or simply vanished from Billy's life; no one ever knew for sure.", "پسر بیلی، رابرت، در ویتنام مرد، یا در ویتنام ناپدید شد، یا به‌سادگی از زندگی بیلی محو شد؛ هیچ‌کس هرگز مطمئن نشد."),
            StoryParagraph("Billy said, 'So it goes.'", "بیلی گفت: «همینطوره.»"),
            StoryParagraph("Edgar Derby, the kind teacher, the man who had tried to protect Billy, died in Dresden, shot by a firing squad for stealing a teapot.", "ادگار دِربی، معلم مهربان، مردی که تلاش کرده بود از بیلی محافظت کند، در درسدن مرد، توسط جوخه آتش تیرباران شد برای دزدیدن قوری چای."),
            StoryParagraph("He was arrested, court-martialed, and executed for stealing a teapot — a teapot, in a city that had just been destroyed by firebombs.", "او دستگیر، محاکمه و اعدام شد برای دزدیدن یک قوری — یک قوری، در شهری که تازه با بمب‌های آتشین نابود شده بود."),
            StoryParagraph("The irony was so great, the injustice so absurd, that Vonnegut did not even bother to comment on it; he simply said, 'So it goes.'", "طنز آنقدر بزرگ بود، بی‌عدالتی آنقدر پوچ، که ونه‌گات حتی زحمت تفسیرش را نکشید؛ تنها گفت: «همینطوره.»"),
            StoryParagraph("So it goes.", "همینطوره."),
            StoryParagraph("Roland Weary died of gangrene, in a boxcar, in a war, for nothing; Paul Lazzaro died, years later, in prison, for nothing.", "رولاند ویر از قانقاریا مرد، در واگن باری، در جنگ، برای هیچ؛ پاول لازارو سال‌ها بعد، در زندان، برای هیچ مرد."),
            StoryParagraph("Robert Kennedy was shot in Los Angeles; Martin Luther King was shot in Memphis; John Kennedy was shot in Dallas; and each time, the novel says, 'So it goes.'", "رابرت کندی در لس‌آنجلس تیر خورد؛ مارتین لوتر کینگ در ممفیس تیر خورد؛ جان کندی در دالاس تیر خورد؛ و هر بار، رمان می‌گوید: «همینطوره.»"),
            StoryParagraph("Vietnamese civilians were killed in My Lai; American students were killed at Kent State; Jews were killed in concentration camps; and each time, the novel says, 'So it goes.'", "غیرنظامیان ویتنامی در مای لای کشته شدند؛ دانشجویان آمریکایی در کنت استیت کشته شدند؛ یهودیان در اردوگاه‌های کار اجباری کشته شدند؛ و هر بار، رمان می‌گوید: «همینطوره.»"),
            StoryParagraph("The phrase becomes a mantra, a prayer, a way of surviving the unbearable; the phrase becomes the only response the novel can make to the horror of history.", "این عبارت تبدیل به مانترا می‌شود، دعا، شیوه‌ای برای زنده ماندن در ناتحمل‌پذیر؛ این عبارت تبدیل به تنها پاسخی می‌شود که رمان می‌تواند به وحشت تاریخ بدهد."),
            StoryParagraph("The Tralfamadorians said that death is not the end; the Tralfamadorians said that everyone lives forever, in some moment.", "ترالفامادوری‌ها گفتند مرگ پایان نیست؛ ترالفامادوری‌ها گفتند همه برای همیشه زنده‌اند، در لحظه‌ای."),
            StoryParagraph("And Billy believed them; Billy believed that all the dead were still alive, in the past, in memory, in the great landscape of time.", "و بیلی باورشان کرد؛ بیلی باور کرد همه مردگان هنوز زنده‌اند، در گذشته، در حافظه، در منظره بزرگ زمان."),
            StoryParagraph("And in that belief, in that impossible hope, in that beautiful lie, Billy found the only comfort available to him.", "و در آن باور، در آن امید ناممکن، در آن دروغ زیبا، بیلی تنها تسلی موجود برایش را یافت."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Slaughterhouse-Five, published in 1969, is one of the most important novels of the twentieth century, and one of the most personal.", "کشتارگاه پنج، منتشرشده در ۱۹۶۹، یکی از مهم‌ترین رمان‌های قرن بیستم و یکی از شخصی‌ترین است."),
            StoryParagraph("Kurt Vonnegut wrote it, in part, to make sense of his own experience as a prisoner of war in Dresden, where he had survived the firebombing.", "کورت ونه‌گات آن را، بخشی، برای معنادار کردن تجربه خودش به‌عنوان اسیر جنگی در درسدن نوشت، جایی که از بمباران آتشین جان به‌در برده بود."),
            StoryParagraph("He had been a young American soldier, captured by the Germans, sent to Dresden, put to work in a factory, hidden in a meat locker during the raid.", "سرباز جوان آمریکایی بوده، توسط آلمانی‌ها اسیر شده، به درسدن فرستاده شده، در کارخانه‌ای کار کرده، در طول حمله در سردخانه گوشت پنهان شده بود."),
            StoryParagraph("He came out of the slaughterhouse to find a city of ash, a city of corpses, a city of nothing.", "از کشتارگاه بیرون آمده بود و شهری از خاکستر یافت، شهری از اجساد، شهری از هیچ."),
            StoryParagraph("He had been ordered to help collect the bodies; he had been ordered to burn them; he had been ordered to do the unthinkable.", "به او دستور داده شده بود کمک به جمع‌آوری اجساد کند؛ دستور داده شده بود بسوزاندشان؛ دستور داده شده بود کار غیرقابل تصور را بکند."),
            StoryParagraph("And for twenty-five years after the war, he could not write about it; he could not speak about it; he could not think about it.", "و تا بیست و پنج سال پس از جنگ، نمی‌توانست درباره‌اش بنویسد؛ نمی‌توانست صحبتش کند؛ نمی‌توانست درباره‌اش فکر کند."),
            StoryParagraph("He tried, many times; he wrote drafts; he threw them away; he could not find the words.", "بارها تلاش کرد؛ پیش‌نویس نوشت؛ دور انداخت؛ نمی‌توانست کلمات را بیابد."),
            StoryParagraph("And then, finally, he wrote Slaughterhouse-Five — a novel that is not really a novel, a memoir that is not really a memoir, a book that is not really a book.", "و بعد، سرانجام، کشتارگاه پنج را نوشت — رمانی که واقعاً رمان نیست، خاطره‌ای که واقعاً خاطره نیست، کتابی که واقعاً کتاب نیست."),
            StoryParagraph("It is a hybrid, a collage, a mixture of fact and fiction, of memory and imagination, of horror and humor.", "دو رگه‌ای است، کلاژی، مخلوطی از واقعیت و داستان، از حافظه و تخیل، از وحشت و شوخ‌طبعی."),
            StoryParagraph("The first chapter is about Vonnegut himself — about his return to Dresden, about his attempts to write the book, about his conversations with an old war buddy.", "فصل اول درباره خود ونه‌گات است — درباره بازگشتش به درسدن، درباره تلاش‌هایش برای نوشتن کتاب، درباره گفتگوهایش با یک رفیق قدیمی جنگ."),
            StoryParagraph("The rest of the novel is about Billy Pilgrim — about his life, his time travels, his captivity, his survival.", "بقیه رمان درباره بیلی پیلگریم است — درباره زندگی‌اش، سفرهایش در زمان، اسارتش، بقایش."),
            StoryParagraph("It is, in its own way, one of the most honest books ever written about war, because it refuses to make war meaningful.", "به شیوه خودش، یکی از صادقانه‌ترین کتاب‌های نوشته‌شده درباره جنگ است، چون از معنادار کردن جنگ امتناع می‌کند."),
            StoryParagraph("Most war novels try to make sense of war; they try to find meaning in the horror; they try to redeem the suffering.", "بیشتر رمان‌های جنگی تلاش می‌کنند به جنگ معنا دهند؛ تلاش می‌کنند در وحشت معنا بیابند؛ تلاش می‌کنند رنج را رستگار کنند."),
            StoryParagraph("Slaughterhouse-Five does not; Slaughterhouse-Five refuses; Slaughterhouse-Five simply says: 'So it goes.'", "کشتارگاه پنج نمی‌کند؛ کشتارگاه پنج امتناع می‌کند؛ کشتارگاه پنج به‌سادگی می‌گوید: «همینطوره.»"),
            StoryParagraph("And in that refusal, in that simple phrase, in that almost-nothing of a sentence, there is more wisdom than in all the war novels ever written.", "و در آن امتناع، در آن عبارت ساده، در آن تقریباً هیچِ یک جمله، خردی بیش از تمام رمان‌های جنگی نوشته‌شده هست."),
            StoryParagraph("Because the truth is that war is senseless; the truth is that death is random; the truth is that suffering is meaningless.", "زیرا حقیقت این است که جنگ بی‌معناست؛ حقیقت این است که مرگ تصادفی است؛ حقیقت این است که رنج بی‌معناست."),
            StoryParagraph("And to try to make sense of these things, to try to find meaning in these things, is to lie — is to pretend that the universe is kinder than it is.", "و تلاش برای معنادار کردن این چیزها، تلاش برای یافتن معنا در این چیزها، دروغ گفتن است — تظاهر به اینکه جهان مهربان‌تر از آن است که هست."),
            StoryParagraph("Vonnegut does not lie; Vonnegut tells the truth; Vonnegut says, 'So it goes,' and lets us make of it what we will.", "ونه‌گات دروغ نمی‌گوید؛ ونه‌گات حقیقت را می‌گوید؛ ونه‌گات می‌گوید «همینطوره» و می‌گذارد هر چه می‌خواهیم از آن بسازیم."),
            StoryParagraph("The novel's structure reflects its message; the story is told out of order, jumping back and forth in time, just as Billy Pilgrim jumps back and forth in time.", "ساختار رمان پیامش را بازتاب می‌دهد؛ داستان بی‌ترتیب گفته می‌شود، جلو و عقب در زمان می‌پرد، همانطور که بیلی پیلگریم جلو و عقب در زمان می‌پرد."),
            StoryParagraph("This is not a gimmick; this is not a trick; this is the way memory actually works, the way consciousness actually works, the way life actually works.", "این ترفند نیست؛ این حقه نیست؛ این روشی است که حافظه واقعاً کار می‌کند، روشی که آگاهی واقعاً کار می‌کند، روشی که زندگی واقعاً کار می‌کند."),
            StoryParagraph("We do not experience time as a line; we experience it as a jumble, a chaos, a storm of moments, all mixed together.", "ما زمان را همچون خط تجربه نمی‌کنیم؛ همچون آشوبی تجربه می‌کنیم، هرج‌ومرجی، طوفانی از لحظات، همه با هم آمیخته."),
            StoryParagraph("And the Tralfamadorians, the aliens who see all time at once, are not really aliens; they are a metaphor for the way we could see time, if we were wise enough.", "و ترالفامادوری‌ها، موجودات فضایی که تمام زمان را یکجا می‌بینند، واقعاً موجود فضایی نیستند؛ استعاره‌ای هستند برای روشی که می‌توانستیم زمان را ببینیم، اگر به اندازه کافی فرزانه بودیم."),
            StoryParagraph("If we could see all time at once, we would not mourn the dead; we would see them still alive, in their own moments, in their own lives.", "اگر می‌توانستیم تمام زمان را یکجا ببینیم، برای مردگان عزاداری نمی‌کردیم؛ می‌دیدیمشان هنوز زنده، در لحظات خودشان، در زندگی‌های خودشان."),
            StoryParagraph("If we could see all time at once, we would not fear death; we would see our own death as one moment among many, no more important than any other.", "اگر می‌توانستیم تمام زمان را یکجا ببینیم، از مرگ نمی‌ترسیدیم؛ مرگ خودمان را همچون یک لحظه میان بسیاری می‌دیدیم، نه مهم‌تر از هر لحظه دیگری."),
            StoryParagraph("If we could see all time at once, we would not suffer; we would simply accept, and let go, and say, 'So it goes.'", "اگر می‌توانستیم تمام زمان را یکجا ببینیم، رنج نمی‌کشیدیم؛ تنها می‌پذیرفتیم و رها می‌کردیم و می‌گفتیم: «همینطوره.»"),
            StoryParagraph("But we cannot see all time at once; we are not Tralfamadorians; we are humans, and we suffer, and we mourn, and we die.", "اما نمی‌توانیم تمام زمان را یکجا ببینیم؛ ترالفامادوری نیستیم؛ انسانیم و رنج می‌کشیم و عزاداری می‌کنیم و می‌میریم."),
            StoryParagraph("And maybe that is the point; maybe we are meant to suffer; maybe we are meant to mourn; maybe we are meant to die.", "و شاید همین نکته است؛ شاید مقدر شده رنج بکشیم؛ شاید مقدر شده عزاداری کنیم؛ شاید مقدر شده بمیریم."),
            StoryParagraph("Maybe the meaning of life is not to escape suffering, but to live through it; not to escape death, but to face it; not to escape life, but to embrace it.", "شاید معنای زندگی فرار از رنج نیست، بلکه زیستن از میان آن است؛ فرار از مرگ نیست، بلکه رویارویی با آن؛ فرار از زندگی نیست، بلکه در آغوش گرفتنش."),
            StoryParagraph("Vonnegut wrote the novel not to make sense of war, but to make peace with it; not to find meaning in horror, but to live with horror.", "ونه‌گات رمان را نه برای معنادار کردن جنگ نوشت، بلکه برای صلح با آن؛ نه برای یافتن معنا در وحشت، بلکه برای زندگی با وحشت."),
            StoryParagraph("And in that living with horror, in that peace with the impossible, in that acceptance of the unacceptable, he found a kind of wisdom.", "و در آن زندگی با وحشت، در آن صلح با ناممکن، در آن پذیرش ناپذیرفتنی، نوعی خرد یافت."),
            StoryParagraph("It is not a cheerful wisdom; it is not a comforting wisdom; but it is wisdom, nonetheless.", "خرد شادی نیست؛ خرد تسلی‌بخش نیست؛ اما به هر حال خرد است."),
            StoryParagraph("It is the wisdom of the survivor; it is the wisdom of the witness; it is the wisdom of the man who has seen the worst and lived to tell about it.", "خرد بازمانده است؛ خرد شاهد است؛ خرد مردی است که بدترین را دیده و زنده مانده تا بگوید."),
            StoryParagraph("And what he tells us is this: that life is terrible, and life is beautiful, and both of these are true.", "و آنچه به ما می‌گوید این است: زندگی هولناک است و زندگی زیبا است و هر دو درستند."),
            StoryParagraph("That we should not try to make sense of the senseless; that we should not try to understand the incomprehensible.", "که نباید تلاش کنیم به بی‌معنا معنا دهیم؛ نباید تلاش کنیم نامفهوم را بفهمیم."),
            StoryParagraph("That we should simply live, and love, and lose, and mourn, and continue.", "که تنها باید زندگی کنیم و عشق بورزیم و از دست بدهیم و عزاداری کنیم و ادامه دهیم."),
            StoryParagraph("And that when someone dies — as everyone does, eventually — we should simply say, 'So it goes.'", "و اینکه وقتی کسی می‌میرد — همانطور که همه در نهایت می‌میرند — تنها باید بگوییم: «همینطوره.»"),
            StoryParagraph("The novel is not a happy book; it is not a sad book; it is a true book.", "رمان کتاب شادی نیست؛ کتاب اندوه نیست؛ کتابی راستین است."),
            StoryParagraph("It is a book about what happened, and what happens, and what will always happen, as long as there are humans on this earth.", "کتابی است درباره آنچه اتفاق افتاده، آنچه اتفاق می‌افتد و آنچه همیشه اتفاق می‌افتد، تا وقتی انسان‌هایی روی این زمین باشند."),
            StoryParagraph("And it is a book about how to live with that knowledge — how to live with the knowledge of war, of cruelty, of death.", "و کتابی است درباره چگونگی زندگی با آن دانش — چگونگی زندگی با دانش جنگ، بی‌رحمی، مرگ."),
            StoryParagraph("The answer, Vonnegut suggests, is not to fight against it, not to deny it, not to try to make sense of it.", "پاسخ، ونه‌گات پیشنهاد می‌دهد، جنگیدن با آن نیست، انکارش نیست، تلاش برای معنادار کردنش نیست."),
            StoryParagraph("The answer is simply to accept it, and to say, 'So it goes.'", "پاسخ تنها پذیرش آن است و گفتن «همینطوره.»"),
            StoryParagraph("So it goes.", "همینطوره."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of Billy Pilgrim is the story of all of us, in our own wars, in our own lives, in our own deaths.", "زیرا داستان بیلی پیلگریم داستان همه‌مان است، در جنگ‌های خودمان، در زندگی‌های خودمان، در مرگ‌های خودمان."),
            StoryParagraph("And it will continue to be told, as long as there are human beings to tell it.", "و به گفتن ادامه می‌یابد، تا وقتی انسان‌هایی برای گفتنش باشند."),
            StoryParagraph("So it goes.", "همینطوره.")
        )
    )
}